CREATE DATABASE STAR_DB; GO
USE STAR_DB; GO
CREATE TABLE Users(UserID INT IDENTITY PRIMARY KEY,FullName NVARCHAR(200) NOT NULL,Username NVARCHAR(100) UNIQUE NOT NULL,Email NVARCHAR(200) UNIQUE NOT NULL,Phone NVARCHAR(50),PasswordHash NVARCHAR(256) NOT NULL,DateOfBirth DATE,Gender NVARCHAR(20),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),IsActive BIT DEFAULT 1);
CREATE TABLE Profiles(ProfileID INT IDENTITY PRIMARY KEY,UserID INT UNIQUE NOT NULL REFERENCES Users(UserID),Bio NVARCHAR(500),ProfileImage NVARCHAR(500),Website NVARCHAR(250));
CREATE TABLE Posts(PostID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),Content NVARCHAR(MAX),ImagePath NVARCHAR(500),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),IsDeleted BIT DEFAULT 0);
CREATE TABLE Comments(CommentID INT IDENTITY PRIMARY KEY,PostID INT NOT NULL REFERENCES Posts(PostID),UserID INT NOT NULL REFERENCES Users(UserID),CommentText NVARCHAR(500) NOT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
CREATE TABLE Likes(LikeID INT IDENTITY PRIMARY KEY,PostID INT NOT NULL REFERENCES Posts(PostID),UserID INT NOT NULL REFERENCES Users(UserID),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),CONSTRAINT UQ_Likes UNIQUE(PostID,UserID));
CREATE TABLE Followers(FollowerID INT IDENTITY PRIMARY KEY,FollowerUserID INT NOT NULL REFERENCES Users(UserID),FollowingUserID INT NOT NULL REFERENCES Users(UserID),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),CONSTRAINT UQ_Followers UNIQUE(FollowerUserID,FollowingUserID));
CREATE TABLE Stories(StoryID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),ImagePath NVARCHAR(500),[Text] NVARCHAR(500),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),ExpiresAt DATETIME2 NOT NULL);
CREATE TABLE Conversations(ConversationID INT IDENTITY PRIMARY KEY,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
CREATE TABLE Messages(MessageID INT IDENTITY PRIMARY KEY,ConversationID INT NOT NULL REFERENCES Conversations(ConversationID),SenderID INT NOT NULL REFERENCES Users(UserID),MessageText NVARCHAR(MAX),ImagePath NVARCHAR(500),SentAt DATETIME2 DEFAULT SYSDATETIME(),IsRead BIT DEFAULT 0);
CREATE TABLE Calls(CallID INT IDENTITY PRIMARY KEY,CallerID INT NOT NULL REFERENCES Users(UserID),ReceiverID INT NOT NULL REFERENCES Users(UserID),CallType NVARCHAR(30),StartTime DATETIME2 DEFAULT SYSDATETIME(),EndTime DATETIME2,CallStatus NVARCHAR(50));
CREATE TABLE Notifications(NotificationID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),SenderID INT NOT NULL REFERENCES Users(UserID),NotificationType NVARCHAR(100),NotificationText NVARCHAR(255),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),IsRead BIT DEFAULT 0);
CREATE TABLE SavedPosts(SavedID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),PostID INT NOT NULL REFERENCES Posts(PostID),SavedAt DATETIME2 DEFAULT SYSDATETIME(),CONSTRAINT UQ_Saved UNIQUE(UserID,PostID));
CREATE TABLE Achievements(AchievementID INT IDENTITY PRIMARY KEY,AchievementName NVARCHAR(150),[Description] NVARCHAR(250),Points INT,Icon NVARCHAR(200));
CREATE TABLE UserAchievements(UserAchievementID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),AchievementID INT NOT NULL REFERENCES Achievements(AchievementID),EarnedAt DATETIME2 DEFAULT SYSDATETIME());
CREATE TABLE Settings(SettingID INT IDENTITY PRIMARY KEY,UserID INT UNIQUE NOT NULL REFERENCES Users(UserID),IsPrivate BIT DEFAULT 0,AllowMessages BIT DEFAULT 1,ShowOnlineStatus BIT DEFAULT 1,DarkMode BIT DEFAULT 1,FontSize INT DEFAULT 12);
CREATE TABLE ActivityLog(ActivityID INT IDENTITY PRIMARY KEY,UserID INT NOT NULL REFERENCES Users(UserID),ActivityType NVARCHAR(150),ActivityDescription NVARCHAR(500),ActivityDate DATETIME2 DEFAULT SYSDATETIME());
CREATE INDEX IX_Posts_User ON Posts(UserID);CREATE INDEX IX_Messages_Conversation ON Messages(ConversationID);CREATE INDEX IX_Notifications_User ON Notifications(UserID);
